import { readFileSync, readdirSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const DIR = '/workspace/probe/corpus/block-scalars';
const EXE = '/workspace/dataset/test14_executable';
const files = readdirSync(DIR).sort();
let ok = 0,
  err = 0;
const show = new Set(process.argv.slice(2));
for (const f of files) {
  const inp = readFileSync(`${DIR}/${f}`, 'utf8');
  let out, rc;
  try {
    out = execFileSync(EXE, ['--a', inp], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    rc = 0;
    ok++;
  } catch (e) {
    out = (e.stdout || '') + (e.stderr || '');
    rc = e.status;
    err++;
  }
  if (show.size === 0 || show.has(f)) {
    console.log(`##### ${f} rc=${rc}`);
    console.log('  IN : ' + JSON.stringify(inp));
    console.log('  OUT: ' + JSON.stringify(out));
  }
}
console.log(`\ntotal=${files.length} rc0=${ok} rcNonZero=${err}`);

