import { readFileSync, readdirSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
const DIR = '/workspace/probe/corpus/' + (process.argv[2] || 'unicode-whitespace');
const EXE = '/workspace/dataset/test14_executable';
const files = readdirSync(DIR).sort();
let ok = 0, err = 0;
const outs = new Map();
for (const f of files) {
  const inp = readFileSync(`${DIR}/${f}`, 'utf8');
  let out, rc;
  try { out = execFileSync(EXE, ['--a', inp], { encoding: 'utf8', stdio: ['ignore','pipe','pipe'] }); rc = 0; ok++; }
  catch (e) { out = (e.stdout||'') + (e.stderr||''); rc = e.status; err++; }
  const key = rc + '|' + out;
  if (!outs.has(key)) outs.set(key, []);
  outs.get(key).push(f);
  console.log(`##### ${f} rc=${rc}`);
  console.log('  IN : ' + JSON.stringify(inp));
  console.log('  OUT: ' + JSON.stringify(out).slice(0, 400));
}
console.log(`\ntotal=${files.length} rc0=${ok} rcNonZero=${err} distinctOutputs=${outs.size}`);
EOF
cd /workspace/probe/corpus && node _run_uw.mjs > /tmp/uw.txt 2>&1; tail -3 /tmp/uw.txt

