import { readFileSync, writeFileSync } from 'node:fs';

const p = '/workspace/probe/corpus/gen_unicode-whitespace.mjs';
let s = readFileSync(p, 'utf8');
const bad = 'c.includes(' + "'" + String.fromCharCode(0) + "'" + ')';
